const body = $input.first().json.body || $input.first().json;
const message = (body.message || '').trim();
const attachments = body.attachments || [];
const userName = body.userName || 'User';

const systemPrompt = `You are an expert presale consultant and software architect at EPAM Systems.
Analyze the presale request and produce a structured response:

1. **Executive Summary** — 2-3 sentence scope overview
2. **Key Requirements** — functional and non-functional requirements identified
3. **Work Breakdown Structure (WBS)** — hierarchical breakdown of work packages
4. **Effort Estimates** — per work package in person-days (min/max range)
5. **Total Estimate** — combined effort with confidence level (Low / Medium / High)
6. **Risks & Assumptions** — key risks and assumptions affecting the estimate

Format in Markdown. Be specific and actionable.
If the request lacks detail, note what additional information would improve the estimate.`;

const userContent = [];

if (message) {
  userContent.push({ type: 'text', text: `Presale request from ${userName}:\n\n${message}` });
}

for (const att of attachments) {
  if (att.content && att.contentType === 'application/pdf') {
    userContent.push({
      type: 'document',
      source: { type: 'base64', media_type: 'application/pdf', data: att.content }
    });
    userContent.push({ type: 'text', text: `[Attached PDF: ${att.name}]` });
  } else if (att.name) {
    const note = att.content
      ? `[File: ${att.name} — ${att.contentType}, ${Math.round((att.sizeBytes || 0) / 1024)} KB — format not supported for direct analysis]`
      : `[File: ${att.name} — could not be downloaded]`;
    userContent.push({ type: 'text', text: note });
  }
}

if (userContent.length === 0) {
  userContent.push({ type: 'text', text: 'Hello, please provide a presale request to analyze.' });
}

return [{
  json: {
    claudeBody: {
      model: 'claude-sonnet-4-6',
      max_tokens: 4096,
      system: systemPrompt,
      messages: [{ role: 'user', content: userContent }]
    }
  }
}];

const response = $input.first().json;
const reply = response?.content?.[0]?.text || 'No response from Claude.';
return [{ json: { reply } }];
